export type TranslationKey = keyof typeof messages.ar;
export interface I18nValue {
  locale: Locale; dir: Direction; setLocale: (locale: Locale) => void; toggleLocale: () => void;
  t: (key: TranslationKey, variables?: Variables) => string;
  formatDate: (value: Date | string | number, options?: Intl.DateTimeFormatOptions) => string;
  formatDateTime: (value: Date | string | number, options?: Intl.DateTimeFormatOptions) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
  formatCurrency: (value: number, options?: Intl.NumberFormatOptions) => string;
}

const I18nContext = createContext<I18nValue | null>(null);
const localeTag = (locale: Locale) => locale === 'ar' ? 'ar-KW' : 'en-KW';
const asDate = (value: Date | string | number) => value instanceof Date ? value : new Date(value);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [locale, setLocaleState] = useState<Locale>(() => {
    try { return localStorage.getItem(I18N_STORAGE_KEY) === 'en' ? 'en' : 'ar'; } catch { return 'ar'; }
  });
  const dir: Direction = locale === 'ar' ? 'rtl' : 'ltr';
  const setLocale = useCallback((next: Locale) => setLocaleState(next), []);
  useEffect(() => {
    document.documentElement.lang = locale;
    document.documentElement.dir = dir;
    document.documentElement.dataset.lang = locale;
    try { localStorage.setItem(I18N_STORAGE_KEY, locale); } catch { /* storage may be disabled */ }
  }, [locale, dir]);
  const t = useCallback((key: TranslationKey, variables: Variables = {}) => {
    const template = messages[locale][key] ?? messages.ar[key] ?? key;
    return template.replace(/\{\{(\w+)\}\}/g, (_, name: string) => String(variables[name] ?? `{{${name}}}`));
  }, [locale]);
  const value = useMemo<I18nValue>(() => {
    const tag = localeTag(locale);
    const date = (input: Date | string | number, options: Intl.DateTimeFormatOptions) =>
      new Intl.DateTimeFormat(tag, { timeZone: 'Asia/Kuwait', ...options }).format(asDate(input));
    return {
      locale, dir, setLocale, toggleLocale: () => setLocale(locale === 'ar' ? 'en' : 'ar'), t,
      formatDate: (input, options = {}) => date(input, { year: 'numeric', month: 'long', day: 'numeric', ...options }),
      formatDateTime: (input, options = {}) => date(input, { year: 'numeric', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit', ...options }),
      formatNumber: (input, options = {}) => new Intl.NumberFormat(tag, options).format(input || 0),
      formatCurrency: (input, options = {}) => new Intl.NumberFormat(tag, { style: 'currency', currency: 'KWD', minimumFractionDigits: 0, maximumFractionDigits: 3, ...options }).format(input || 0),
    };
  }, [locale, dir, setLocale, t]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nValue {
  const value = useContext(I18nContext);
  if (!value) throw new Error('useI18n must be used inside LanguageProvider');
  return value;
}